class ShareModelForm(forms.ModelForm):
    """Инструмент"""

    class Meta:
        model = Share
        fields = "__all__"


class WatchlistForm(forms.ModelForm):
    def __init__(self, *args, owner, **kwargs):
        self.owner = owner
        super().__init__(*args, **kwargs)

    class Meta:
        model = Watchlist
        fields = ("name",)

    def clean_name(self):
        name = self.cleaned_data["name"].strip()
        duplicate = Watchlist.objects.filter(owner=self.owner, name__iexact=name)
        if self.instance.pk:
            duplicate = duplicate.exclude(pk=self.instance.pk)
        if duplicate.exists():
            raise forms.ValidationError("У вас уже есть список с таким названием.")
        return name


class WatchlistEntryForm(forms.Form):
    share = forms.ModelChoiceField(queryset=Share.objects.none())

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields["share"].queryset = Share.objects.order_by("name")


class PriceAlertForm(forms.Form):
    direction = forms.ChoiceField(choices=PriceAlert.Direction.choices)
    target_price = forms.DecimalField(
        max_digits=20,
        decimal_places=8,
        min_value=0.00000001,
    )

from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.shortcuts import get_object_or_404, redirect, render
from django.utils import timezone
from django.views.decorators.http import require_POST

from dashboard.forms import PriceAlertForm, WatchlistEntryForm, WatchlistForm
from dashboard.models import AlertNotification, PriceAlert, Watchlist, WatchlistEntry


@login_required(login_url="user:auth")
def monitoring(request):
    watchlists = (
        Watchlist.objects.filter(owner=request.user)
        .prefetch_related("entries__share", "entries__alerts")
        .order_by("name")
    )
    notifications = (
        AlertNotification.objects.filter(alert__entry__watchlist__owner=request.user)
        .select_related("alert__entry__share", "alert__entry__watchlist")
        .order_by("-created_at")[:50]
    )
    return render(
        request,
        "dashboard/monitoring.html",
        {
            "watchlists": watchlists,
            "notifications": notifications,
            "watchlist_form": WatchlistForm(owner=request.user),
            "entry_form": WatchlistEntryForm(),
            "alert_form": PriceAlertForm(),
        },
    )


@login_required(login_url="user:auth")
@require_POST
def create_watchlist(request):
    form = WatchlistForm(request.POST, owner=request.user)
    if form.is_valid():
        watchlist = form.save(commit=False)
        watchlist.owner = request.user
        watchlist.save()
        messages.success(request, "Список наблюдения создан.")
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:monitoring:index")


@login_required(login_url="user:auth")
@require_POST
def add_watchlist_entry(request, watchlist_id):
    watchlist = get_object_or_404(Watchlist, pk=watchlist_id, owner=request.user)
    form = WatchlistEntryForm(request.POST)
    if form.is_valid():
        WatchlistEntry.objects.get_or_create(
            watchlist=watchlist,
            share=form.cleaned_data["share"],
        )
        messages.success(request, "Акция добавлена в список.")
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:monitoring:index")


@login_required(login_url="user:auth")
@require_POST
def add_price_alert(request, entry_id):
    entry = get_object_or_404(
        WatchlistEntry,
        pk=entry_id,
        watchlist__owner=request.user,
    )
    form = PriceAlertForm(request.POST)
    if form.is_valid():
        PriceAlert.objects.get_or_create(
            entry=entry,
            direction=form.cleaned_data["direction"],
            target_price=form.cleaned_data["target_price"],
        )
        messages.success(request, "Ценовой уровень сохранён.")
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:monitoring:index")


@login_required(login_url="user:auth")
@require_POST
def delete_watchlist_entry(request, entry_id):
    entry = get_object_or_404(
        WatchlistEntry,
        pk=entry_id,
        watchlist__owner=request.user,
    )
    entry.delete()
    return redirect("dashboard:monitoring:index")


@login_required(login_url="user:auth")
@require_POST
def mark_notification_read(request, notification_id):
    notification = get_object_or_404(
        AlertNotification,
        pk=notification_id,
        alert__entry__watchlist__owner=request.user,
    )
    if notification.read_at is None:
        notification.read_at = timezone.now()
        notification.save(update_fields=("read_at",))
    return redirect("dashboard:monitoring")

from django.db import models
from django.conf import settings


class Share(models.Model):
    """Акция"""

    figi = models.CharField(max_length=255, unique=True)
    isin = models.CharField(max_length=255)
    name = models.CharField(max_length=255, verbose_name="Наименование компании")
    ticker = models.CharField(max_length=10, unique=True, verbose_name="Тикер")
    currency = models.CharField(max_length=20, verbose_name="Валюта")
    uid = models.CharField(max_length=255, unique=True)
    last_price = models.FloatField(blank=True, null=True, verbose_name="Текущая цена")
    is_trend_high = models.BooleanField(
        blank=True, null=True, verbose_name="Растет цена"
    )
    updated_at = models.DateTimeField(auto_now=True, blank=True, null=True)

    class Meta:
        verbose_name = "Акция"
        verbose_name_plural = "Акции"


class Watchlist(models.Model):
    owner = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="watchlists"
    )
    name = models.CharField(max_length=100)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(fields=("owner", "name"), name="uniq_watchlist_owner_name")
        ]
        ordering = ("name",)

    def __str__(self):
        return self.name


class WatchlistEntry(models.Model):
    watchlist = models.ForeignKey(
        Watchlist, on_delete=models.CASCADE, related_name="entries"
    )
    share = models.ForeignKey(
        Share, on_delete=models.CASCADE, related_name="watchlist_entries"
    )
    added_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=("watchlist", "share"), name="uniq_watchlist_share"
            )
        ]
        ordering = ("share__name",)


class PriceAlert(models.Model):
    class Direction(models.TextChoices):
        ABOVE = "above", "Выше цели"
        BELOW = "below", "Ниже цели"

    entry = models.ForeignKey(
        WatchlistEntry, on_delete=models.CASCADE, related_name="alerts"
    )
    direction = models.CharField(max_length=5, choices=Direction.choices)
    target_price = models.DecimalField(max_digits=20, decimal_places=8)
    is_active = models.BooleanField(default=True)
    created_at = models.DateTimeField(auto_now_add=True)
    triggered_at = models.DateTimeField(blank=True, null=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=("entry", "direction", "target_price"),
                name="uniq_alert_target_per_entry",
            )
        ]
        ordering = ("target_price",)


class AlertNotification(models.Model):
    alert = models.OneToOneField(
        PriceAlert, on_delete=models.CASCADE, related_name="notification"
    )
    observed_price = models.DecimalField(max_digits=20, decimal_places=8)
    created_at = models.DateTimeField(auto_now_add=True)
    read_at = models.DateTimeField(blank=True, null=True)

    class Meta:
        ordering = ("-created_at",)


class Portfolio(models.Model):
    owner = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="portfolios"
    )
    name = models.CharField(max_length=100)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(fields=("owner", "name"), name="uniq_portfolio_owner_name")
        ]
        ordering = ("name",)

    def __str__(self):
        return self.name


class PortfolioPosition(models.Model):
    portfolio = models.ForeignKey(
        Portfolio, on_delete=models.CASCADE, related_name="positions"
    )
    share = models.ForeignKey(
        Share, on_delete=models.PROTECT, related_name="portfolio_positions"
    )
    quantity = models.DecimalField(max_digits=20, decimal_places=8, default=0)
    average_price = models.DecimalField(max_digits=20, decimal_places=8, default=0)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=("portfolio", "share"), name="uniq_portfolio_share"
            ),
            models.CheckConstraint(condition=models.Q(quantity__gte=0), name="portfolio_position_nonnegative"),
        ]
        ordering = ("share__name",)


class PortfolioTransaction(models.Model):
    class Side(models.TextChoices):
        BUY = "buy", "Покупка"
        SELL = "sell", "Продажа"

    portfolio = models.ForeignKey(
        Portfolio, on_delete=models.CASCADE, related_name="transactions"
    )
    share = models.ForeignKey(
        Share, on_delete=models.PROTECT, related_name="portfolio_transactions"
    )
    side = models.CharField(max_length=4, choices=Side.choices)
    quantity = models.DecimalField(max_digits=20, decimal_places=8)
    unit_price = models.DecimalField(max_digits=20, decimal_places=8)
    total_value = models.DecimalField(max_digits=20, decimal_places=8)
    realized_pnl = models.DecimalField(max_digits=20, decimal_places=8, default=0)
    created_at = models.DateTimeField(auto_now_add=True)

    class Meta:
        constraints = [
            models.CheckConstraint(condition=models.Q(quantity__gt=0), name="portfolio_transaction_positive_quantity"),
            models.CheckConstraint(condition=models.Q(unit_price__gt=0), name="portfolio_transaction_positive_price"),
        ]
        ordering = ("-created_at",)

