from decimal import Decimal

from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.shortcuts import get_object_or_404, redirect, render
from django.views.decorators.http import require_POST

from dashboard.forms import PortfolioForm, PortfolioTransactionForm
from dashboard.models import Portfolio, PortfolioTransaction
from dashboard.services.portfolio import as_amount, execute_transaction


@login_required(login_url="user:auth")
def portfolios(request):
    owned_portfolios = Portfolio.objects.filter(owner=request.user).prefetch_related(
        "positions__share", "transactions__share"
    )
    portfolio_rows = []
    for portfolio in owned_portfolios:
        market_value = sum(
            (
                position.quantity * Decimal(str(position.share.last_price or 0))
                for position in portfolio.positions.all()
            ),
            Decimal("0"),
        )
        cost_basis = sum(
            (position.quantity * position.average_price for position in portfolio.positions.all()),
            Decimal("0"),
        )
        portfolio_rows.append(
            {
                "portfolio": portfolio,
                "market_value": as_amount(market_value),
                "unrealized_pnl": as_amount(market_value - cost_basis),
                "transaction_form": PortfolioTransactionForm(),
            }
        )

    return render(
        request,
        "dashboard/portfolios.html",
        {"portfolio_rows": portfolio_rows, "portfolio_form": PortfolioForm()},
    )


@login_required(login_url="user:auth")
@require_POST
def create_portfolio(request):
    form = PortfolioForm(request.POST)
    if form.is_valid():
        portfolio = form.save(commit=False)
        portfolio.owner = request.user
        portfolio.save()
        messages.success(request, "Портфель создан.")
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:portfolio-list")


@login_required(login_url="user:auth")
@require_POST
def record_transaction(request, portfolio_id):
    portfolio = get_object_or_404(Portfolio, pk=portfolio_id, owner=request.user)
    form = PortfolioTransactionForm(request.POST)
    if form.is_valid():
        try:
            execute_transaction(
                portfolio=portfolio,
                share=form.cleaned_data["share"],
                side=form.cleaned_data["side"],
                quantity=form.cleaned_data["quantity"],
                unit_price=form.cleaned_data["unit_price"],
            )
            messages.success(request, "Операция записана.")
        except ValueError as error:
            messages.error(request, str(error))
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:portfolio-list")

{% extends "dashboard/base.html" %}

{% block title %}
<title>Виртуальные портфели</title>
{% endblock %}

{% block content %}
<h1 class="h3 mb-4">Виртуальные портфели</h1>

{% if messages %}
    {% for message in messages %}
        <div class="alert alert-info" role="status">{{ message }}</div>
    {% endfor %}
{% endif %}

<section class="mb-4">
    <h2 class="h5">Новый портфель</h2>
    <form method="post" action="{% url 'dashboard:portfolios:create' %}" class="form-inline">
        {% csrf_token %}
        {{ portfolio_form.name }}
        <button class="btn btn-primary ml-2" type="submit">Создать</button>
    </form>
</section>

{% for row in portfolio_rows %}
<section class="mb-5">
    <h2 class="h5">{{ row.portfolio.name }}</h2>
    <p>Текущая стоимость: {{ row.market_value }} · Нереализованный P/L: {{ row.unrealized_pnl }}</p>

    <h3 class="h6">Позиции</h3>
    <div class="table-responsive">
        <table class="table table-striped">
            <thead><tr><th>Акция</th><th>Количество</th><th>Средняя цена</th><th>Текущая цена</th><th>Стоимость</th><th>P/L</th></tr></thead>
            <tbody>
            {% for position in row.portfolio.positions.all %}
                <tr>
                    <td>{{ position.share.ticker }} · {{ position.share.name }}</td>
                    <td>{{ position.quantity }}</td>
                    <td>{{ position.average_price }}</td>
                    <td>{{ position.share.last_price|default:"—" }}</td>
                    <td>{{ position.quantity|floatformat:2 }} × {{ position.share.last_price|default:0 }}</td>
                    <td>{% if position.share.last_price %}{{ position.quantity|floatformat:2 }} × ({{ position.share.last_price }} − {{ position.average_price }}){% else %}—{% endif %}</td>
                </tr>
            {% empty %}
                <tr><td colspan="6" class="text-muted">Операций пока нет.</td></tr>
            {% endfor %}
            </tbody>
        </table>
    </div>

    <h3 class="h6 mt-4">Новая операция</h3>
    <form method="post" action="{% url 'dashboard:portfolios:transaction' row.portfolio.id %}" class="form-inline">
        {% csrf_token %}
        {{ row.transaction_form.share }}
        {{ row.transaction_form.side }}
        {{ row.transaction_form.quantity }}
        {{ row.transaction_form.unit_price }}
        <button class="btn btn-outline-primary ml-2" type="submit">Записать операцию</button>
    </form>

    <h3 class="h6 mt-4">История операций</h3>
    <div class="table-responsive">
        <table class="table table-sm">
            <thead><tr><th>Дата</th><th>Акция</th><th>Тип</th><th>Количество</th><th>Цена</th><th>Сумма</th><th>Реализованный P/L</th></tr></thead>
            <tbody>
            {% for transaction in row.portfolio.transactions.all %}
                <tr>
                    <td>{{ transaction.created_at }}</td>
                    <td>{{ transaction.share.ticker }}</td>
                    <td>{{ transaction.get_side_display }}</td>
                    <td>{{ transaction.quantity }}</td>
                    <td>{{ transaction.unit_price }}</td>
                    <td>{{ transaction.total_value }}</td>
                    <td>{{ transaction.realized_pnl }}</td>
                </tr>
            {% empty %}
                <tr><td colspan="7" class="text-muted">История пуста.</td></tr>
            {% endfor %}
            </tbody>
        </table>
    </div>
</section>
{% empty %}
<p class="text-muted">Создайте портфель, чтобы начать виртуальные операции.</p>
{% endfor %}
{% endblock %}

from decimal import Decimal

from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.shortcuts import get_object_or_404, redirect, render
from django.views.decorators.http import require_POST

from dashboard.forms import PortfolioForm, PortfolioTransactionForm
from dashboard.models import Portfolio, PortfolioTransaction
from dashboard.services.portfolio import as_amount, execute_transaction


@login_required(login_url="user:auth")
def portfolios(request):
    owned_portfolios = Portfolio.objects.filter(owner=request.user).prefetch_related(
        "positions__share", "transactions__share"
    )
    portfolio_rows = []
    for portfolio in owned_portfolios:
        position_rows = []
        market_value = Decimal("0")
        cost_basis = Decimal("0")
        for position in portfolio.positions.all():
            last_price = (
                Decimal(str(position.share.last_price))
                if position.share.last_price is not None
                else None
            )
            current_value = as_amount(position.quantity * last_price) if last_price else Decimal("0")
            position_cost = as_amount(position.quantity * position.average_price)
            position_rows.append(
                {
                    "position": position,
                    "last_price": last_price,
                    "market_value": current_value,
                    "unrealized_pnl": as_amount(current_value - position_cost),
                }
            )
            market_value += current_value
            cost_basis += position_cost
        portfolio_rows.append(
            {
                "portfolio": portfolio,
                "positions": position_rows,
                "market_value": as_amount(market_value),
                "unrealized_pnl": as_amount(market_value - cost_basis),
                "transaction_form": PortfolioTransactionForm(),
            }
        )

    return render(
        request,
        "dashboard/portfolios.html",
        {"portfolio_rows": portfolio_rows, "portfolio_form": PortfolioForm()},
    )


@login_required(login_url="user:auth")
@require_POST
def create_portfolio(request):
    form = PortfolioForm(request.POST)
    if form.is_valid():
        portfolio = form.save(commit=False)
        portfolio.owner = request.user
        portfolio.save()
        messages.success(request, "Портфель создан.")
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:portfolio-list")


@login_required(login_url="user:auth")
@require_POST
def record_transaction(request, portfolio_id):
    portfolio = get_object_or_404(Portfolio, pk=portfolio_id, owner=request.user)
    form = PortfolioTransactionForm(request.POST)
    if form.is_valid():
        try:
            execute_transaction(
                portfolio=portfolio,
                share=form.cleaned_data["share"],
                side=form.cleaned_data["side"],
                quantity=form.cleaned_data["quantity"],
                unit_price=form.cleaned_data["unit_price"],
            )
            messages.success(request, "Операция записана.")
        except ValueError as error:
            messages.error(request, str(error))
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:portfolio-list")

