    <h2 class="h5">{{ watchlist.name }}</h2>
    <form method="post" action="{% url 'dashboard:monitoring:add-entry' watchlist.id %}" class="form-inline mb-3">
        {% csrf_token %}
        {{ entry_form.share }}
        <button class="btn btn-outline-primary ml-2" type="submit">Добавить акцию</button>
    </form>
    {% if watchlist.entries.all %}
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr><th>Тикер</th><th>Цена</th><th>Целевые уровни</th><th>Действия</th></tr>
            </thead>
            <tbody>
            {% for entry in watchlist.entries.all %}
                <tr>
                    <td>{{ entry.share.ticker }} · {{ entry.share.name }}</td>
                    <td>{{ entry.share.last_price|default:"—" }} {{ entry.share.currency }}</td>
