                        <form method="post" action="{% url 'dashboard:monitoring:add-alert' entry.id %}" class="form-inline mt-2">
                            {% csrf_token %}
                            {{ alert_form.direction }}
                            {{ alert_form.target_price }}
                            <button class="btn btn-sm btn-outline-secondary ml-2" type="submit">Задать</button>
                        </form>
                    </td>
                    <td>
                        <form method="post" action="{% url 'dashboard:monitoring:delete-entry' entry.id %}">
                            {% csrf_token %}
