from decimal import Decimal

from django.db import transaction

from dashboard.models import InvestmentStrategy, Share, StrategyTrade
from dashboard.services.portfolio import as_amount


@transaction.atomic
def process_price_update(share: Share, price: Decimal | float | str, market_at):
    market_price = as_amount(price)
    processed_trades = []
    strategies = InvestmentStrategy.objects.select_for_update().filter(
        share=share,
        is_active=True,
    )

    for strategy in strategies:
        if strategy.last_processed_at and strategy.last_processed_at >= market_at:
            continue

        if strategy.current_quantity == 0 and market_price <= strategy.buy_price:
            trade, created = StrategyTrade.objects.get_or_create(
                strategy=strategy,
                side=StrategyTrade.Side.BUY,
                market_at=market_at,
                defaults={
                    "market_price": market_price,
                    "quantity": strategy.quantity,
                },
            )
            if created:
                strategy.current_quantity = strategy.quantity
                strategy.average_buy_price = market_price
                processed_trades.append(trade)
        elif strategy.current_quantity > 0 and market_price >= strategy.sell_price:
            realized_pnl = as_amount(
                (market_price - strategy.average_buy_price) * strategy.current_quantity
            )
            trade, created = StrategyTrade.objects.get_or_create(
                strategy=strategy,
                side=StrategyTrade.Side.SELL,
                market_at=market_at,
                defaults={
                    "market_price": market_price,
                    "quantity": strategy.current_quantity,
                    "realized_pnl": realized_pnl,
                },
            )
            if created:
                strategy.realized_pnl += realized_pnl
                strategy.current_quantity = Decimal("0")
                strategy.average_buy_price = Decimal("0")
                processed_trades.append(trade)

        strategy.last_processed_at = market_at
        strategy.save(
            update_fields=(
                "current_quantity",
                "average_buy_price",
                "realized_pnl",
                "last_processed_at",
            )
        )

    return processed_trades

from django import forms

from .models import (
    InvestmentStrategy,
    Portfolio,
    PortfolioTransaction,
    PriceAlert,
    Share,
    Watchlist,
)


class ShareModelForm(forms.ModelForm):
    """Инструмент"""

    class Meta:
        model = Share
        fields = "__all__"


class WatchlistForm(forms.ModelForm):
    def __init__(self, *args, owner, **kwargs):
        self.owner = owner
        super().__init__(*args, **kwargs)

    class Meta:
        model = Watchlist
        fields = ("name",)

    def clean_name(self):
        name = self.cleaned_data["name"].strip()
        duplicate = Watchlist.objects.filter(owner=self.owner, name__iexact=name)
        if self.instance.pk:
            duplicate = duplicate.exclude(pk=self.instance.pk)
        if duplicate.exists():
            raise forms.ValidationError("У вас уже есть список с таким названием.")
        return name


class WatchlistEntryForm(forms.Form):
    share = forms.ModelChoiceField(queryset=Share.objects.none())

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields["share"].queryset = Share.objects.order_by("name")


class PriceAlertForm(forms.Form):
    direction = forms.ChoiceField(choices=PriceAlert.Direction.choices)
    target_price = forms.DecimalField(
        max_digits=20,
        decimal_places=8,
        min_value=0.00000001,
    )


class PortfolioForm(forms.ModelForm):
    class Meta:
        model = Portfolio
        fields = ("name",)


class PortfolioTransactionForm(forms.Form):
    share = forms.ModelChoiceField(queryset=Share.objects.none())
    side = forms.ChoiceField(choices=PortfolioTransaction.Side.choices)
    quantity = forms.DecimalField(max_digits=20, decimal_places=8, min_value=0.00000001)
    unit_price = forms.DecimalField(max_digits=20, decimal_places=8, min_value=0.00000001)

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields["share"].queryset = Share.objects.order_by("name")


class PriceHistoryFilterForm(forms.Form):
    share = forms.ModelChoiceField(queryset=Share.objects.none(), required=False)
    start_date = forms.DateField(
        required=False, widget=forms.DateInput(attrs={"type": "date"})
    )
    end_date = forms.DateField(
        required=False, widget=forms.DateInput(attrs={"type": "date"})
    )

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields["share"].queryset = Share.objects.order_by("name")

    def clean(self):
        cleaned_data = super().clean()
        start_date = cleaned_data.get("start_date")
        end_date = cleaned_data.get("end_date")
        if start_date and end_date and start_date > end_date:
            raise forms.ValidationError("Начало периода должно быть не позже его конца.")
        return cleaned_data


class InvestmentStrategyForm(forms.ModelForm):
    share = forms.ModelChoiceField(queryset=Share.objects.none())

    class Meta:
        model = InvestmentStrategy
        fields = ("name", "share", "buy_price", "sell_price", "quantity")

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields["share"].queryset = Share.objects.order_by("name")

    def clean(self):
        cleaned_data = super().clean()
        buy_price = cleaned_data.get("buy_price")
        sell_price = cleaned_data.get("sell_price")
        if buy_price and sell_price and sell_price <= buy_price:
            raise forms.ValidationError("Цена продажи должна быть выше цены покупки.")
        return cleaned_data

from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.shortcuts import get_object_or_404, redirect, render
from django.views.decorators.http import require_POST

from dashboard.forms import InvestmentStrategyForm
from dashboard.models import InvestmentStrategy


@login_required(login_url="user:auth")
def strategies(request):
    strategy_list = (
        InvestmentStrategy.objects.filter(owner=request.user)
        .select_related("share")
        .prefetch_related("trades")
    )
    return render(
        request,
        "dashboard/strategies.html",
        {"strategies": strategy_list, "form": InvestmentStrategyForm()},
    )


@login_required(login_url="user:auth")
@require_POST
def create_strategy(request):
    form = InvestmentStrategyForm(request.POST)
    if form.is_valid():
        strategy = form.save(commit=False)
        strategy.owner = request.user
        strategy.save()
        messages.success(request, "Стратегия создана и запущена.")
    else:
        messages.error(request, form.errors.as_text())
    return redirect("dashboard:strategies:index")


@login_required(login_url="user:auth")
@require_POST
def toggle_strategy(request, strategy_id):
    strategy = get_object_or_404(InvestmentStrategy, pk=strategy_id, owner=request.user)
    strategy.is_active = not strategy.is_active
    strategy.save(update_fields=("is_active",))
    return redirect("dashboard:strategies:index")

{% extends "dashboard/base.html" %}

{% block title %}
<title>Симулятор стратегий</title>
{% endblock %}

{% block content %}
<h1 class="h3 mb-4">Симулятор стратегий</h1>

{% if messages %}
    {% for message in messages %}
        <div class="alert alert-info" role="status">{{ message }}</div>
    {% endfor %}
{% endif %}

<section class="mb-5">
    <h2 class="h5">Новая стратегия</h2>
    <form method="post" action="{% url 'dashboard:strategies:create' %}" class="form-inline">
        {% csrf_token %}
        {{ form.name }}
        {{ form.share }}
        {{ form.buy_price }}
        {{ form.sell_price }}
        {{ form.quantity }}
        <button class="btn btn-primary ml-2" type="submit">Запустить</button>
    </form>
    {% if form.non_field_errors %}<div class="text-danger">{{ form.non_field_errors }}</div>{% endif %}
</section>

{% for strategy in strategies %}
<section class="mb-5 border-bottom pb-4">
    <div class="d-flex justify-content-between align-items-center">
        <h2 class="h5 mb-0">{{ strategy.name }} · {{ strategy.share.ticker }}</h2>
        <form method="post" action="{% url 'dashboard:strategies:toggle' strategy.id %}">
            {% csrf_token %}
            <button class="btn btn-sm btn-outline-secondary" type="submit">{% if strategy.is_active %}Приостановить{% else %}Возобновить{% endif %}</button>
        </form>
    </div>
    <p class="mt-2">Покупка ≤ {{ strategy.buy_price }} · Продажа ≥ {{ strategy.sell_price }} · Количество {{ strategy.quantity }}</p>
    <p>Состояние: {% if strategy.is_active %}активна{% else %}приостановлена{% endif %} · Открытая позиция: {{ strategy.current_quantity }} · Средняя цена: {{ strategy.average_buy_price }} · Реализованный P/L: {{ strategy.realized_pnl }}</p>
    <h3 class="h6">Журнал сделок</h3>
    <div class="table-responsive">
        <table class="table table-sm">
            <thead><tr><th>Рыночное время</th><th>Операция</th><th>Количество</th><th>Цена</th><th>Реализованный P/L</th></tr></thead>
            <tbody>
            {% for trade in strategy.trades.all %}
                <tr><td>{{ trade.market_at }}</td><td>{{ trade.get_side_display }}</td><td>{{ trade.quantity }}</td><td>{{ trade.market_price }}</td><td>{{ trade.realized_pnl }}</td></tr>
            {% empty %}
                <tr><td colspan="5" class="text-muted">Сделок пока нет.</td></tr>
            {% endfor %}
            </tbody>
        </table>
    </div>
</section>
{% empty %}
<p class="text-muted">Создайте стратегию для виртуального моделирования сделок.</p>
{% endfor %}
{% endblock %}

